y":{"work_id":"@insane","language":"nl"},"before":null,"after":{"work_id":"@insane","language":"nl","bound_author_id":813,"text":"De zeventienjarige Emily ontdekt dat een seriemoordenaar haar op het oog heeft. Hij weet veel over haar en heeft al vier slachtoffers gemaakt. Bij iedere moord blijft een goudkleurig bedeltje achter. Terwijl de politie de dader probeert te vinden, wil Emily voorkomen dat zij het volgende slachtoffer wordt. Haar vastberadenheid om te overleven staat tegenover een tegenstander die zich niet gemakkelijk laat opsporen. Deze jeugdthriller volgt haar strijd tegen de dreiging.","source_type":"official_publisher","source_name":"Uitgeverij De Fontein","source_url":"https://www.uitgeverijdefontein.nl/boek/insane/","evidence":[{"url":"https://www.uitgeverijdefontein.nl/boek/insane/","checkedAt":"2026-11-05","facts":["Exact ISBN9789026186790, Nederlands, Hardback, auteur en editie","Emily17, seriemoordenaar, vier slachtoffers, gouden bedeltjes, politie probeert dader te stoppen"],"dateConflict":"Publisher20October vs bibliographic27October2026; only uncontested year2026 stored."},{"url":"https://www.uitgeverijdefontein.nl/nieuws/interview-met-mel-wallis-de-vries-over-haar-nieuwe-boek-insane/","checkedAt":"2026-11-05","facts":["Auteursinterview bevestigt Emily en goudkleurige bedeltjes; geen spoilerdetails overgenomen"]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-05T10:35:00Z","review_batch":"popular-three-20261105"}}]'::jsonb)->((r->>'seq')::int-1);expected:=a->'after';expectedkey:=a->'key';
 for kv in select * from jsonb_each(expected) loop if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Unresolved scoped parent';end if;expected:=jsonb_set(expected,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;end loop;
 for kv in select * from jsonb_each(expectedkey) loop if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then expectedkey:=jsonb_set(expectedkey,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;end loop;
 execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into normalized using expected;
 select jsonb_object_agg(key,normalized->key) into expected from jsonb_each(expected);
 if a is null or r->>'relation' is distinct from a->>'relation' or r->'key' is distinct from expectedkey or r->'before_row'<>'null'::jsonb or not (r->'after_row' @> expected) then raise exception 'Receipt outside exact reviewed scope';end if;
 if r->'after_row' ? 'id' then ids:=jsonb_set(ids,array[a->>'ref'],r->'after_row'->'id');end if;end loop;
